import {readFile,writeFile} from 'node:fs/promises';import {randomUUID} from 'node:crypto';import {portableMessage,scrub} from './safe-content.js';import {createMcpManager} from './runtime/mcp.js';
export function validatePack(input){if(input.version!==1||typeof input.name!=='string'||!Array.isArray(input.servers)||input.servers.length>20)throw Error('Expected version 1 MCP pack');const keys=['name','type','transport','command','args','envNames','url','authEnv','capabilities'];for(const c of input.servers){if(Object.keys(c).some(k=>!keys.includes(k))||scrub(JSON.stringify(c))!==JSON.stringify(c))throw Error('Unsafe tool pack: secret or unsupported field');if(c.envNames?.some(n=>!/^[A-Z_][A-Z0-9_]*$/.test(n)))throw Error('Use environment variable names only');if(c.type==='http'||c.transport==='http'){const u=new URL(c.url);if(u.username||u.password||u.search||u.hash||!['http:','https:'].includes(u.protocol))throw Error('Invalid MCP endpoint');}else if(typeof c.command!=='string'||!c.command.trim()||c.args?.some(x=>/token=|api[_-]?key=|bearer\s/i.test(x)))throw Error('Invalid MCP command');}return {version:1,name:input.name.slice(0,100),servers:input.servers};}
export async function installPack(store,input){const pack=validatePack(input),manager=createMcpManager(store.home),added=[];try{for(const server of pack.servers)added.push(await manager.add(server));}catch(e){for(const c of added)await manager.remove(c.id);throw e;}return store.saveRecord('packs',{id:randomUUID(),...pack,serverIds:added.map(c=>c.id),connected:false});}
export async function exportChat(store,sessionId,file){const session=await store.getSession(sessionId),bundle={version:1,type:'apex-chat',title:scrub(session.title),source:{sessionId:session.id,projectId:session.projectId},messages:session.messages.filter(m=>['user','assistant'].includes(m.role)).map(portableMessage)};if(JSON.stringify(bundle).length>2e6)throw Error('Bundle exceeds 2MB');await writeFile(file,JSON.stringify(bundle,null,2),{flag:'wx',mode:0o600});return {file,messages:bundle.messages.length};}
export async function importChat(store,projectId,file){const raw=await readFile(file);if(raw.length>2e6)throw Error('Bundle exceeds 2MB');const bundle=JSON.parse(raw);if(bundle.version!==1||bundle.type!=='apex-chat'||!Array.isArray(bundle.messages))throw Error('Unsupported chat bundle');if(bundle.messages.some(m=>!['user','assistant'].includes(m.role)||typeof m.content!=='string'))throw Error('Unsafe chat messages');const session=await store.createSession({projectId,title:scrub(bundle.title||'Imported chat')});for(const m of bundle.messages)await store.appendMessage(session.id,{...portableMessage(m),id:randomUUID(),importedFrom:{sessionId:bundle.source?.sessionId,messageId:m.id},untrusted:true});return session;}
export async function evaluationCase(store,{sessionId,jobId,expected,file,trainingCandidate=false}){const session=await store.getSession(sessionId);if(jobId&&(await store.record('jobs',jobId))?.sessionId!==sessionId)throw Error('Job/session mismatch');const events=jobId?await store.records('events',{jobId}):[],value={id:randomUUID(),version:1,type:trainingCandidate?'training-candidate':'apex-evaluation',projectId:session.projectId,source:{sessionId,jobId},request:session.messages.find(m=>m.role==='user')?.content||'',expected:String(expected||''),evidence:events.filter(e=>e.type==='tool_evidence'||e.type==='team_review'),modelClaims:session.messages.filter(m=>m.role==='assistant').map(portableMessage),trainingAdmitted:false};const clean=JSON.parse(scrub(JSON.stringify(value)));await writeFile(file,JSON.stringify(clean,null,2),{flag:'wx',mode:0o600});await store.saveRecord('evaluations',clean);return {file,id:clean.id,type:clean.type};}
